from typing import List

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.test_models.cloud.common import (enter_test_dedicated_state,
                                                                           exit_test_dedicated_state,
                                                                           cleanup_after_test_dedicated_state)


def general_siso_auto_cloud_entering_test_dedicated_state_and_running_nr_performance_pucch(testing_env: TestingEnv,
                                                                                           cells_names: List[str],
                                                                                           interval: float,
                                                                                           beam_pattern_id: List[int],
                                                                                           reception_slot: int,
                                                                                           expectation_slot: int,
                                                                                           prb_offset: int,
                                                                                           largest_prb_index: int,
                                                                                           ru_mode: str,
                                                                                           pucch_format: str,
                                                                                           pucch_symbols_number: int,
                                                                                           pucch_payload_content: int,
                                                                                           payload_bit_number: int,
                                                                                           format3_additional_dmrs: str,
                                                                                           start_timeout: int = 90,
                                                                                           stop_timeout: int = 90):
    """
    Based on:
    QC Test ID: 203674
    QC Test Name: [2.0] CB010411_L_Operability_CB007120_B_Entering_Test_Dedicated_State_and_run_NR_Performance_PUCCH_F0_Via_Web

    Should report to:
    QC Test ID: 70674
    QC Test Name: General_SiSo_Auto_Cloud_Entering_Test_Dedicated_State_And_Running_NR_Performance_PUCCH

    :param testing_env: testing environment prepared for this test case
    :param cells_names: names of cells for which NR Performance PUCCH test (with same set of parameters) should be run;
                        can be taken from "NRCELL ID" field of cell details in DU WebEM;
                        i.e. ['NRCELL-1', 'NRCELL-3']
    :param interval: reporting time interval to be set before starting NR Performance PUCCH test; from <0.1, 3600> range
    :param beam_pattern_id: beam pattern ID to be set before starting NR Performance PUCCH test; i.e. [1, 1, 1, 1]
    :param reception_slot: reception slot bit pattern to be set before starting NR Performance PUCCH test; from <0, 1023> range
    :param expectation_slot: expectation slot bit pattern to be set before starting NR Performance PUCCH test; from <0, 1023> range
    :param prb_offset: PRB offset to be set before starting NR Performance PUCCH test; from <0, 272> range
    :param largest_prb_index: largest PRB index to be set before starting NR Performance PUCCH test; from <0, 272> range
    :param ru_mode: RU mode to be set before starting NR Performance PUCCH test; one of the following: 'NR_Only', 'MSR', 'Customize_1'
    :param pucch_format: PUCCH format to be set before starting NR Performance PUCCH test; one of the following: 'F0', 'F1', 'F2', 'F3'
    :param pucch_symbols_number: number of PUCCH symbols to be set before starting NR Performance PUCCH test; one of the following: 1, 2, 4, 14
    :param pucch_payload_content: content of PUCCH payload to be set before starting NR Performance PUCCH test; from <0, 4294967295> range
    :param payload_bit_number: number of payload bits to be set before starting NR Performance PUCCH test; one of the following: 1, 2, 4, 16, 22
    :param format3_additional_dmrs: specifies whether additional DMRS should be enabled; one of the following: 'Enabled', 'Disabled'
    :param start_timeout: timeout (in seconds) for starting NR Performance PUCCH test; defaults to 90
    :param stop_timeout: timeout (in seconds) for stopping NR Performance PUCCH test; defaults to 90
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    bts.cells.check_if_names_exist(names=cells_names)

    for du in bts.dus:
        enter_test_dedicated_state(du)

        for cell_name in cells_names:
            try:
                _start_nr_performance_pucch_test(du,
                                                 cell_name,
                                                 interval,
                                                 beam_pattern_id,
                                                 reception_slot,
                                                 expectation_slot,
                                                 prb_offset,
                                                 largest_prb_index,
                                                 ru_mode,
                                                 pucch_format,
                                                 pucch_symbols_number,
                                                 pucch_payload_content,
                                                 payload_bit_number,
                                                 format3_additional_dmrs,
                                                 start_timeout)
                _stop_nr_performance_pucch_test(du,
                                                cell_name,
                                                stop_timeout)
            except ResultError as exc:
                errors.add_from_exception(exc)

        exit_test_dedicated_state(du)

    errors.check()


def teardown_for_general_siso_auto_cloud_entering_test_dedicated_state_and_running_nr_performance_pucch(testing_env: TestingEnv):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    for du in bts.dus:
        cleanup_after_test_dedicated_state(du, errors)


def _start_nr_performance_pucch_test(du,
                                     cell_name,
                                     interval,
                                     beam_pattern_id,
                                     reception_slot,
                                     expectation_slot,
                                     prb_offset,
                                     largest_prb_index,
                                     ru_mode,
                                     pucch_format,
                                     pucch_symbols_number,
                                     pucch_payload_content,
                                     payload_bit_number,
                                     format3_additional_dmrs,
                                     timeout):
    for cell in du.cells:
        if cell.name == cell_name:
            du.test_model.start_nr_performance_pucch_test(cell=cell,
                                                          interval=interval,
                                                          beam_pattern_id=beam_pattern_id,
                                                          reception_slot=reception_slot,
                                                          expectation_slot=expectation_slot,
                                                          prb_offset=prb_offset,
                                                          largest_prb_index=largest_prb_index,
                                                          ru_mode=ru_mode,
                                                          pucch_format=pucch_format,
                                                          pucch_symbols_number=pucch_symbols_number,
                                                          pucch_payload_content=pucch_payload_content,
                                                          payload_bit_number=payload_bit_number,
                                                          format3_additional_dmrs=format3_additional_dmrs,
                                                          timeout=timeout)


def _stop_nr_performance_pucch_test(du, cell_name, timeout):
    for cell in du.cells:
        if cell.name == cell_name:
            du.test_model.stop_nr_performance_test(cell=cell,
                                                   timeout=timeout)
